<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue';import {pmsApi} from './api';import PmsFormDialog from './PmsFormDialog.vue';
const props=defineProps<{task:any;users:any[];csrf?:string}>();const emit=defineEmits(['close','updated']);const search=ref(''),busy=ref(false),error=ref(''),message=ref(''),selected=ref<number[]>((props.task.users||[]).map((u:any)=>u.id)),lookup=ref<any>(null);let version=0,debounce:ReturnType<typeof setTimeout>|undefined;
const shown=computed(()=>props.users.filter(u=>(u.name+' '+u.email).toLowerCase().includes(search.value.trim().toLowerCase())));const validEmail=computed(()=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(search.value.trim()));
watch(search,()=>{const v=++version;lookup.value=null;if(debounce)clearTimeout(debounce);if(!validEmail.value||props.users.some(u=>u.email?.toLowerCase()===search.value.trim().toLowerCase()))return;debounce=setTimeout(async()=>{try{const d=await pmsApi('tasks/'+props.task.id+'/invite-check?email='+encodeURIComponent(search.value.trim()));if(v===version)lookup.value=d;}catch(e){if(v===version)error.value=(e as Error).message;}},200);});onUnmounted(()=>{version++;if(debounce)clearTimeout(debounce);});
async function assign(u?:any){if(busy.value)return;busy.value=true;error.value='';try{const d=await pmsApi('tasks/'+props.task.id+'/board',props.csrf,'PATCH',{assignee_id:u?.id||null,assignee_action:!u?'clear':selected.value.includes(u.id)?'remove':'add'});selected.value=d.task.users.map((u:any)=>u.id);emit('updated');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function invite(manual=false){busy.value=true;error.value='';try{const d=await pmsApi('tasks/'+props.task.id+'/invite',props.csrf,'POST',{email:search.value.trim(),delivery_method:manual?'manual':'email'});if(manual){await navigator.clipboard.writeText(d.invitation_url);message.value='Invitation link created and copied.';}else message.value=d.message||'Invitation sent.';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><PmsFormDialog class="pms-work-assignee-modal" title="Assign issue" :subtitle="task.title" centered @close="emit('close')"><p v-if="error" class="notice admin-error">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><div class="input-group mb-3"><span class="input-group-text"><i class="fa fa-search"></i></span><input v-model="search" type="search" class="form-control" placeholder="Search a name or enter an email to invite..." aria-label="Search assignees" autofocus></div><div class="list-group pms-work-assignee-list"><button v-if="!search||'unassigned'.includes(search.toLowerCase())" class="list-group-item list-group-item-action d-flex align-items-center gap-2" :disabled="busy" @click="assign()"><span class="work-avatar m-0 d-inline-flex align-items-center justify-content-center"><i class="fa fa-user-slash text-muted"></i></span><span>Unassigned</span><i v-if="!selected.length" class="fa fa-check text-success ms-auto"></i></button><button v-for="u in shown" :key="u.id" class="list-group-item list-group-item-action d-flex align-items-center gap-2" :disabled="busy" @click="assign(u)"><img class="work-avatar m-0" :src="u.profile_img||'/pms-assets/assets/img/user-picture.png'" alt=""><span><strong class="d-block">{{u.name}}</strong><small class="text-muted">{{u.email}}</small></span><i v-if="selected.includes(u.id)" class="fa fa-check text-success ms-auto"></i></button><button v-if="lookup?.exists" class="list-group-item list-group-item-action d-flex align-items-center gap-2" :disabled="busy||!lookup.assignable" @click="assign(lookup.employee)"><img class="work-avatar m-0" :src="lookup.employee.profile_img||'/pms-assets/assets/img/user-picture.png'" alt=""><span><strong class="d-block">{{lookup.employee.name}}</strong><small class="d-block text-muted">{{lookup.employee.email}}</small><small class="d-block" :class="lookup.assignable?'text-success':'text-warning'">{{lookup.assignable?'Existing employee - click to assign.':'This employee is not currently eligible for assignment.'}}</small></span><i class="fa fa-user-plus text-primary ms-auto"></i></button><div v-else-if="lookup&&!lookup.exists" class="list-group-item d-flex align-items-center gap-2"><span class="work-avatar m-0 d-inline-flex align-items-center justify-content-center bg-label-primary"><i class="fa fa-envelope"></i></span><span class="flex-grow-1"><strong>Invite new employee</strong><small class="d-block text-muted">{{search}}</small></span><button class="btn btn-sm btn-primary" :disabled="busy" @click="invite()"><i class="fa fa-paper-plane me-1"></i>Send email</button><button class="btn btn-sm btn-icon btn-label-primary" aria-label="Create and copy invitation link" :disabled="busy" @click="invite(true)"><i class="fa fa-copy"></i></button></div><div v-if="!shown.length&&!lookup&&!validEmail&&search&&!('unassigned'.includes(search.toLowerCase()))" class="work-empty">No employees found.</div></div></PmsFormDialog></template>
